"""BeautifulUI patterns adapted for the existing local Liquid Glass concept.
MIT source: TurboKach/ai-native-react-components @05dab2d2b5f1f3e40029776e339a486d70491079.
We translate disclosure/alternatives patterns to DOM/CSS; no React demo runtime.
"""
from pathlib import Path
import re
ROOT=Path(__file__).parent
CSS='''
/* Adapted interaction grammar: BeautifulUI TaskRows, ToolChips, ApprovalCard,
   RecommendationCard and PromptBar. Copyright (c) 2026 Turbo. MIT. */
.composer:focus-within{border-color:var(--ink);box-shadow:0 0 0 4px var(--light),inset 0 1px 0 rgba(255,255,255,.16),0 15px 50px var(--shadow)}
.composer-footer-left{display:flex;align-items:center;gap:12px;min-width:0}.shortcut{font-size:10px;color:var(--quiet);display:inline-flex;align-items:center;gap:4px;white-space:nowrap}.shortcut kbd{font:inherit;border:1px solid var(--line);border-radius:5px;padding:2px 5px;background:var(--glass)}.context-strip{display:flex;gap:7px;flex-wrap:wrap;padding:0 0 13px}.context-strip[hidden]{display:none}.context-token{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--glass-edge);border-radius:11px;background:var(--glass);padding:7px 9px;font-size:11px;max-width:100%}.context-token>span{max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.context-token button{width:28px;height:28px;border-radius:50%;background:var(--light);color:var(--ink)}
.task-list.capsules{border:0;display:grid;gap:10px}.task-capsule{overflow:hidden;border:1px solid var(--glass-edge);border-radius:22px;background:var(--glass);backdrop-filter:blur(22px) saturate(0);-webkit-backdrop-filter:blur(22px) saturate(0);box-shadow:inset 0 1px 0 rgba(255,255,255,.09),0 4px 16px var(--shadow);transition:border-radius 220ms cubic-bezier(.23,1,.32,1)}.task-capsule[data-open=true]{border-radius:19px}.capsule-head{display:flex;align-items:center;gap:3px;padding-right:9px}.task-capsule .task-row{border:0;padding:15px 10px 15px 13px;min-height:78px;flex:1;min-width:0}.task-capsule .task-icon{width:34px;height:34px;border-radius:50%;background:transparent;border:1px solid var(--line)}.task-capsule .task-row h3{font-size:12px;line-height:1.55}.task-capsule .task-row p{font-size:10px}.disclosure-toggle{border:0;background:transparent;color:var(--quiet);width:44px;min-width:44px;height:44px;display:grid;place-items:center;border-radius:50%}.disclosure-toggle:hover{background:var(--light)}.disclosure-toggle svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.7;transition:transform 220ms cubic-bezier(.23,1,.32,1)}.disclosure-toggle[aria-expanded=true] svg{transform:rotate(180deg)}
.disclosure-grid{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows 260ms cubic-bezier(.23,1,.32,1),opacity 200ms ease}.disclosure-grid[data-open=true]{grid-template-rows:1fr;opacity:1}.disclosure-inner{min-height:0;overflow:hidden}.task-detail-copy{border-left:1px solid var(--line);margin:0 20px 17px 30px;padding:0 0 0 19px}.task-detail-copy p{font-size:11px;line-height:1.75;color:var(--quiet);margin:0 0 7px}.task-detail-copy a{display:inline-flex;align-items:center;min-height:36px;font-size:11px;text-decoration:underline;text-underline-offset:4px}
.recommendation-note{font-size:11px;color:var(--quiet);line-height:1.7;min-height:36px}.recommendation-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--line);padding-top:10px;margin-top:13px}.recommendation-footer button{border:1px solid var(--glass-edge);background:var(--glass);color:var(--ink);border-radius:20px;min-height:40px;padding:8px 12px;font-size:11px}.recommendation-footer a{font-size:10px;color:var(--quiet);text-decoration:underline;text-underline-offset:4px}.alternative-panel{border-top:1px solid var(--line);margin:13px -18px 0;padding:12px 18px;background:var(--light)}.alternative-panel[hidden]{display:none}.alternative-option{width:100%;display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:54px;padding:9px 4px;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--ink);text-align:left}.alternative-option:last-child{border:0}.alternative-option:hover{background:var(--glass)}.alternative-option span:first-child{font-size:11px}.alternative-option small{display:block;color:var(--quiet);font-size:10px;margin-top:3px}.alternative-option strong{font-weight:400;font-size:12px;white-space:nowrap}.selection-chip{font-size:9px;letter-spacing:1px;text-transform:uppercase;color:var(--quiet);margin:1px 0 8px}
.approval-steps{display:flex;align-items:center;gap:9px;color:var(--quiet);font-size:11px;margin:0 0 17px}.approval-step{display:inline-flex;align-items:center;gap:7px}.approval-step .step-index{width:20px;height:20px;border-radius:50%;border:1px solid var(--line);display:grid;place-items:center;font-size:10px}.approval-step[aria-current=step]{color:var(--ink)}.approval-step[aria-current=step] .step-index{background:var(--forest);color:var(--on-action);border-color:var(--forest)}.step-divider{height:1px;background:var(--line);width:32px}.approval-actions{border-top:1px solid var(--line);padding-top:18px}.approval-actions .primary{transition:opacity 160ms,transform 160ms}.approval-actions .primary:active:not(:disabled){transform:scale(.99)}
.activity-board{border:1px solid var(--glass-edge);border-radius:17px;background:var(--glass);margin:19px 0 24px;overflow:hidden}.activity-header{display:flex;align-items:center;justify-content:space-between;padding:13px 15px;border-bottom:1px solid var(--line);font-size:11px}.activity-header small{font-size:9px;letter-spacing:.8px;color:var(--quiet)}.activity-row{padding:0 9px}.activity-row+.activity-row{border-top:1px solid var(--line)}.activity-toggle{background:transparent;border:0;width:100%;min-height:47px;padding:7px;display:flex;align-items:center;gap:10px;color:var(--ink);text-align:left;font-size:12px}.activity-dot{height:20px;width:20px;flex-shrink:0;border:1px solid var(--control-edge);border-radius:50%;display:grid;place-items:center;font-size:9px}.activity-row[data-state=done] .activity-dot:before{content:"";width:4px;height:7px;border:solid currentColor;border-width:0 1.5px 1.5px 0;transform:rotate(45deg);margin-top:-2px}.activity-row[data-state=done] .activity-dot{background:var(--forest);color:var(--on-action);border-color:var(--forest)}.activity-pill{margin-left:auto;color:var(--quiet);border:1px solid var(--line);background:var(--glass);border-radius:7px;font-size:9px;padding:4px 7px}.activity-chevron{height:13px;width:13px;stroke:currentColor;fill:none;transition:transform 200ms}.activity-toggle[aria-expanded=true] .activity-chevron{transform:rotate(180deg)}.activity-copy{padding:0 12px 13px 38px;font-size:11px;color:var(--quiet);line-height:1.8}.activity-copy p{margin:0}
@media(max-width:600px){.shortcut{display:none}.task-capsule .task-row h3{font-size:12px}.task-capsule .task-row p{font-size:10px}.context-token>span{max-width:210px}.context-token button{width:36px;height:36px}.alternative-panel{margin-left:-20px;margin-right:-20px;padding:10px 20px}.recommendation-note{font-size:12px}.recommendation-footer button{min-height:44px}.activity-pill{font-size:9px;max-width:100px;text-align:center}.activity-toggle{font-size:12px}.activity-copy{font-size:12px}}
@media(prefers-reduced-motion:reduce){.disclosure-grid,.disclosure-toggle svg,.activity-chevron,.task-capsule{transition:none!important}}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){.task-capsule,.activity-board{background:var(--glass-fallback)}}
@media(prefers-reduced-transparency:reduce){.task-capsule,.activity-board{background:var(--glass-fallback);backdrop-filter:none;-webkit-backdrop-filter:none}}
'''
CHEVRON='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>'

def capsule(key,icon,title,description,href,copy):
 return f'''<div class="task-capsule" data-open="false"><div class="capsule-head"><a class="task-row" href="{href}"><span class="task-icon"><svg class="icon"><use href="#{icon}"/></svg></span><div><h3>{title}</h3><p>{description}</p></div></a><button type="button" class="disclosure-toggle" aria-label="Ver detalle: {title}" aria-controls="{key}" aria-expanded="false">{CHEVRON}</button></div><div class="disclosure-grid" id="{key}" data-open="false" aria-hidden="true" inert><div class="disclosure-inner"><div class="task-detail-copy">{copy}</div></div></div></div>'''
HOME_TASKS='<div class="task-list capsules">'+capsule('gift-detail','gift-icon','Un regalo con intención','<span class="status attention">Tu decisión</span>','#comparison','<p>Tres opciones de ejemplo dentro de MXN 1,500.</p><p>Falta elegir y revisar el alcance. No se autorizó ninguna compra.</p><a href="#comparison">Comparar las opciones</a>')+capsule('trip-detail','calendar-icon','Una escapada de fin de semana','Propuesta sin reservas · ejemplo','#task','<p>Objetivo: descanso y tiempo libre.</p><p>Ver la actividad del escenario o ajustar la solicitud. No hay reservas realizadas.</p><a href="#task">Abrir esta tarea</a>')+capsule('week-detail','file-icon','Tu semana, en orden','Organización personal · ejemplo','#tasks','<p>Una vista de tareas con contexto, sin conectar todavía correo ni calendario.</p><a href="#tasks">Ir a mis tareas</a>')+'</div>'
JS='''
// Interaction adaptations from BeautifulUI, MIT (c) 2026 Turbo.
// Data remains synthetic. No background demo timers, external tools or payments.
(()=>{
 const q=s=>document.querySelector(s);const qa=s=>document.querySelectorAll(s);
 function expand(button,panel,open){button.setAttribute('aria-expanded',String(open));panel.dataset.open=String(open);panel.setAttribute('aria-hidden',String(!open));if(open)panel.removeAttribute('inert');else panel.setAttribute('inert','');const c=button.closest('.task-capsule');if(c)c.dataset.open=String(open)}
 qa('.disclosure-toggle').forEach(button=>button.addEventListener('click',()=>expand(button,document.getElementById(button.getAttribute('aria-controls')),button.getAttribute('aria-expanded')!=='true')));
 q('#request').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();q('#request-form').requestSubmit()}});
 q('#file').addEventListener('change',()=>{const file=q('#file').files[0];q('#context-strip').hidden=!file;if(file)q('#context-name').textContent=file.name+' · solo local'});
 q('#remove-context').addEventListener('click',()=>{q('#file').value='';q('#context-strip').hidden=true;q('#request').focus()});
 q('#show-alternatives').addEventListener('click',()=>{const open=q('#show-alternatives').getAttribute('aria-expanded')!=='true';q('#show-alternatives').setAttribute('aria-expanded',String(open));q('#recommendation-alternatives').hidden=!open});
 qa('[data-recommend]').forEach(button=>button.addEventListener('click',()=>{const idx=Number(button.dataset.recommend);chosen=idx;const option=options[idx];q('#home-recommendation-title').textContent=option.title;q('#home-recommendation-price').textContent='MXN '+option.total.toLocaleString('es-MX');q('#recommendation-note').textContent=['Una opción sencilla, debajo del presupuesto.','Cuatro piezas y envío incluido en el ejemplo.','Seis piezas para compartir, dentro del tope.'][idx];q('#prepare-recommendation').dataset.option=String(idx);q('#recommendation-alternatives').hidden=true;q('#show-alternatives').setAttribute('aria-expanded','false');q('#prepare-recommendation').focus()}));
 q('#consent').addEventListener('change',()=>{q('#review-step').removeAttribute('aria-current');q('#authorize-step').removeAttribute('aria-current');q(q('#consent').checked?'#authorize-step':'#review-step').setAttribute('aria-current','step')});
 function renderActivity(rows){const host=q('#activity-rows');host.replaceChildren();rows.forEach((row,i)=>{const wrap=document.createElement('div');wrap.className='activity-row';wrap.dataset.state=row.state;const btn=document.createElement('button');btn.className='activity-toggle';btn.type='button';btn.setAttribute('aria-expanded','false');const id='activity-detail-'+i;btn.setAttribute('aria-controls',id);const dot=document.createElement('span');dot.className='activity-dot';dot.textContent=row.state==='done'?'':String(i+1);dot.setAttribute('aria-hidden','true');const label=document.createElement('span');label.textContent=row.title;const pill=document.createElement('span');pill.className='activity-pill';pill.textContent=row.status;btn.append(dot,label,pill);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','activity-chevron');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M6 9l6 6 6-6');svg.append(path);btn.append(svg);const grid=document.createElement('div');grid.className='disclosure-grid';grid.id=id;grid.dataset.open='false';grid.setAttribute('aria-hidden','true');grid.setAttribute('inert','');const inner=document.createElement('div');inner.className='disclosure-inner';const copy=document.createElement('div');copy.className='activity-copy';const paragraph=document.createElement('p');paragraph.textContent=row.detail;copy.append(paragraph);inner.append(copy);grid.append(inner);btn.addEventListener('click',()=>expand(btn,grid,btn.getAttribute('aria-expanded')!=='true'));wrap.append(btn,grid);host.append(wrap)})}
 renderActivity([{title:'Objetivo preparado',status:'Definido',state:'done',detail:'Ejemplo: un fin de semana tranquilo. Preparar propuestas; no hacer reservas.'},{title:'Comparar opciones',status:'Escenario',state:'idle',detail:'Vista demostrativa de actividad. No se consultó un proveedor ni se ejecutó una búsqueda.'},{title:'Tu propuesta',status:'Pendiente',state:'idle',detail:'En el producto, esta etapa aparecerá cuando exista un resultado real para revisar.'}]);
 q('#request-form').addEventListener('submit',()=>{if(!q('#request').value.trim())return;renderActivity([{title:'Solicitud',status:'Registrada localmente',state:'done',detail:'El texto está en esta página. No fue enviado a un modelo ni a otro servicio.'},{title:'Trabajo del agente',status:'No ejecutado',state:'idle',detail:'El prototipo no tiene un agente conectado. Ninguna animación convierte este estado en una tarea realizada.'}])});
 q('#cancel-task').addEventListener('click',()=>renderActivity([{title:'Tarea detenida',status:'Ejemplo',state:'done',detail:'Cambió el estado local de la demostración. No había trabajo externo ni reservas.'}]));
})();
'''

def enhance(html):
 # Match only the home task list, preserving the separate task index.
 start=html.index('<div class="task-list">');end=html.index('</div><p class="fine-print">Investiga por ti.',start)+len('</div>')
 html=html[:start]+HOME_TASKS+html[end:]
 html=html.replace('<div class="composer-bottom"><button type="button" class="quiet-btn" id="attach">','<div class="context-strip" id="context-strip" hidden><span class="context-token"><span id="context-name"></span><button type="button" id="remove-context" aria-label="Quitar contexto local">×</button></span></div><div class="composer-bottom"><div class="composer-footer-left"><button type="button" class="quiet-btn" id="attach">',1)
 html=html.replace('Agregar contexto</button><button type="submit"','Agregar contexto</button><span class="shortcut"><kbd>Ctrl / Cmd</kbd><kbd>Enter</kbd> enviar</span></div><button type="submit"',1)
 html=html.replace('<h3>Un pequeño ritual de café</h3><p class="muted">La opción que mejor encaja con tu idea.</p>','<p class="selection-chip">Selección de ejemplo</p><h3 id="home-recommendation-title">Ritual de café</h3><p class="recommendation-note" id="recommendation-note">Cuatro piezas y envío incluido en el ejemplo.</p>',1)
 html=html.replace('<span class="price"><small>MXN</small> 1,249</span>','<span class="price" id="home-recommendation-price">MXN 1,249</span>',1)
 anchor='<a class="primary" href="#comparison">Ver las opciones<svg class="icon"><use href="#arrow-icon"/></svg></a>'
 replacement='''<button class="primary" type="button" id="prepare-recommendation" data-option="1">Revisar propuesta<svg class="icon"><use href="#arrow-icon"/></svg></button><div class="recommendation-footer"><button id="show-alternatives" type="button" aria-controls="recommendation-alternatives" aria-expanded="false">Alternativas</button><a href="#comparison">Comparar en detalle</a></div><div id="recommendation-alternatives" class="alternative-panel" hidden><button class="alternative-option" data-recommend="0"><span>Esenciales de café<small>Dos piezas · ejemplo</small></span><strong>MXN 899</strong></button><button class="alternative-option" data-recommend="1"><span>Ritual de café<small>Cuatro piezas · ejemplo</small></span><strong>MXN 1,249</strong></button><button class="alternative-option" data-recommend="2"><span>Café para compartir<small>Seis piezas · ejemplo</small></span><strong>MXN 1,399</strong></button></div>'''
 assert anchor in html;html=html.replace(anchor,replacement,1)
 target='<div class="panel"><span class="status">Cotización de ejemplo</span>'
 assert target in html
 html=html.replace(target,'<div class="panel"><div class="approval-steps" aria-label="Etapas de autorización"><span class="approval-step" id="review-step" aria-current="step"><span class="step-index">1</span>Revisar</span><span class="step-divider" aria-hidden="true"></span><span class="approval-step" id="authorize-step"><span class="step-index">2</span>Autorizar</span></div><span class="status">Cotización de ejemplo</span>',1)
 html=html.replace('<div class="progress-line" aria-hidden="true"><span></span></div>','<div class="activity-board"><div class="activity-header"><span>Actividad de la tarea</span><small>EJEMPLO</small></div><div id="activity-rows"></div></div>',1)
 task_start=html.index('<section class="screen" id="task">')
 task_end=html.index('<section class="screen" id="tasks">')
 task=html[task_start:task_end]
 activity='<div class="activity-board"><div class="activity-header"><span>Actividad de la tarea</span><small>EJEMPLO</small></div><div id="activity-rows"></div></div>'
 task=task.replace(activity,'')
 task=re.sub(r'(<div class="output-note" id="task-summary">.*?</div>)',lambda m:m.group(1)+activity,task,count=1,flags=re.S)
 task=re.sub(r'<ol class="timeline">.*?</ol>','',task,count=1,flags=re.S)
 html=html[:task_start]+task+html[task_end:]
 # Reset the visual step whenever quote data changes, never auto-submit it.
 html=html.replace("$('#consent').checked=false;$('#authorize').disabled=true;", "$('#consent').checked=false;$('#authorize').disabled=true;$('#review-step').setAttribute('aria-current','step');$('#authorize-step').removeAttribute('aria-current');",1)
 html=html.replace('</style>',CSS+'\n</style>',1)
 html=html.replace('</body>','<script>'+JS+'</script><!-- Adaptations: Copyright (c) 2026 Turbo.\n'+(ROOT/'third_party/beautifului/LICENSE').read_text()+'\nSource pinned: https://github.com/TurboKach/ai-native-react-components/tree/05dab2d2b5f1f3e40029776e339a486d70491079 --></body>',1)
 html=html.replace('EXPLORACIÓN DE DISEÑO 03','EXPLORACIÓN DE DISEÑO 04')
 return html
